// 将新增题目合并到主题库
if (typeof NewProblems !== 'undefined') {
    if (NewProblems.math && ProblemBank.math) {
        ProblemBank.math.hard = ProblemBank.math.hard || [];
        ProblemBank.math.hard.push(...NewProblems.math);
    }
    if (NewProblems.english && ProblemBank.english) {
        ProblemBank.english.medium = ProblemBank.english.medium || [];
        ProblemBank.english.medium.push(...NewProblems.english);
    }
    if (NewProblems.chinese && ProblemBank.chinese) {
        ProblemBank.chinese.medium = ProblemBank.chinese.medium || [];
        ProblemBank.chinese.medium.push(...NewProblems.chinese);
    }
}

function getRandomProblem(subjectId, difficulty) {
    const bank = ProblemBank[subjectId];
    if (!bank) return null;
    const pool = bank[difficulty] || bank.easy;
    if (!pool || pool.length === 0) return null;
    return pool[Math.floor(Math.random() * pool.length)];
}